import { LOCALE } from './regions';
import type { Lang } from './types';

/* eslint-disable @typescript-eslint/no-explicit-any */
type Entry = string | ((...a: any[]) => string);
type Dict = Record<string, Entry>;
type Forms = { one?: string; few?: string; many?: string; other?: string };

const pl = (lang: Lang) => (n: number, f: Forms) => {
  const c = new Intl.PluralRules(LOCALE[lang]).select(n) as keyof Forms;
  return f[c] ?? f.other ?? f.many ?? '';
};
type P = ReturnType<typeof pl>;

