const BUILD: Record<Lang, (p: P) => Dict> = { uk, en, es, fr, pl: plDict, de, ru };

const cache: Partial<Record<Lang, Dict>> = {};

export function translator(lang: Lang) {
  const dict = (cache[lang] ??= BUILD[lang](pl(lang)));
  const fallback = (cache.en ??= en(pl('en')));
  return (key: string, ...args: any[]): string => {
    const v = dict[key] ?? fallback[key] ?? key;
    return typeof v === 'function' ? v(...args) : v;
  };
}

export type T = ReturnType<typeof translator>;